package cn.governance;
import java.util.*;
import java.time.*;
import java.nio.charset.StandardCharsets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
@RestController
@RequestMapping("/api/insights")
public class Insights {
 private final JdbcTemplate jdbc;private final AccountService accounts;private final RiskCalculation risk;private final Clock clock;
 public Insights(JdbcTemplate jdbc,AccountService accounts,RiskCalculation risk,Clock clock){this.jdbc=jdbc;this.accounts=accounts;this.risk=risk;this.clock=clock;}
 private AccountService.Account actor(Authentication a){var p=accounts.current(a);if(!p.canReadAll()&&!p.canReadDepartment()&&!p.roles().contains("DEPARTMENT_HANDLER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return p;}
 private List<Map<String,Object>> records(AccountService.Account p,String q){return records(p,q,0,0);}
 private List<Map<String,Object>> records(AccountService.Account p,String q,int page,int size){InputChecks.require(q.length()<=100,"搜索过长");if(!p.canReadAll()&&!p.canReadDepartment())return List.of();return jdbc.queryForList("SELECT r.id,r.matched_person_id AS personId,r.party_name AS name,r.problem_description AS description,r.event_category AS category,r.event_source AS source,r.department_id,r.occurred_at,r.is_completed,l.effective_event_id AS eventId FROM tb_input_record r LEFT JOIN tb_event_source_link l ON l.record_id=r.id WHERE r.is_deleted=0 AND (?=1 OR r.department_id=?) AND (LOCATE(?,r.party_name)>0 OR LOCATE(?,r.problem_description)>0) ORDER BY r.id DESC"+(size>0?" LIMIT "+size+" OFFSET "+((long)(page-1)*size):""),p.canReadAll(),p.departmentId(),q,q);}
 @GetMapping("/events") public Object events(Authentication a,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="50")int size){InputChecks.require(page>0&&page<=1000000&&size>0&&size<=100,"分页无效");return records(actor(a),q,page,size);}
 @GetMapping("/risks") public Object risks(Authentication a,@RequestParam(defaultValue="")String q){var p=actor(a);if(!p.canReadAll())throw new ResponseStatusException(HttpStatus.FORBIDDEN);InputChecks.require(q.length()<=100,"搜索过长");return jdbc.queryForList("SELECT p.id,p.name,JSON_UNQUOTE(JSON_EXTRACT(r.snapshot,'$.finalLevel')) AS level,JSON_EXTRACT(r.snapshot,'$.effectiveCount') AS effectiveCount FROM tb_person p JOIN tb_person_risk r ON r.person_id=p.id WHERE p.merged_into IS NULL AND (LOCATE(?,p.name)>0 OR EXISTS(SELECT 1 FROM tb_input_record x WHERE x.matched_person_id=p.id AND x.is_deleted=0 AND LOCATE(?,x.problem_description)>0)) ORDER BY p.id",q,q);}
 private String scoped(AccountService.Account p){return " r.is_deleted=0 AND ("+(p.canReadAll()?"1=1":p.canReadDepartment()?"r.department_id="+p.departmentId():"1=0")+") AND (LOCATE(?,r.party_name)>0 OR LOCATE(?,r.problem_description)>0) ";}
 @GetMapping("/dashboard") @Transactional(readOnly=true) public Object dashboard(Authentication a,@RequestParam(defaultValue="")String q){
 var p=actor(a);InputChecks.require(q.length()<=100,"搜索过长");String where=scoped(p);
 long reports=jdbc.queryForObject("SELECT COUNT(*) FROM tb_input_record r WHERE "+where,Long.class,q,q);
 long effective=jdbc.queryForObject("SELECT COUNT(DISTINCT l.effective_event_id) FROM tb_input_record r JOIN tb_event_source_link l ON l.record_id=r.id WHERE "+where,Long.class,q,q);
 Map<String,Object> result=new LinkedHashMap<>();result.put("reports",reports);result.put("effectiveEvents",effective);
 for(var item:Map.of("categories","event_category","sources","event_source","departments","department_id").entrySet()){Map<String,Long> grouped=new TreeMap<>();jdbc.queryForList("SELECT "+(item.getKey().equals("departments")?"(SELECT name FROM tb_department d WHERE d.id=r.department_id)":"r."+item.getValue())+" AS label,COUNT(*) AS total FROM tb_input_record r WHERE "+where+" GROUP BY r."+item.getValue(),q,q).forEach(r->grouped.put(Objects.toString(r.get("label"),""),((Number)r.get("total")).longValue()));result.put(item.getKey(),grouped);}
 var tasks=jdbc.queryForList("SELECT state,deadline FROM tb_handling_task t WHERE (?=1 OR department_id=?) AND (?='' OR EXISTS(SELECT 1 FROM tb_input_record r WHERE r.matched_person_id=t.person_id AND "+where+"))",p.canReadAll(),p.departmentId(),q,q,q);
 result.put("tasks",tasks.stream().filter(t->!"CLOSED".equals(t.get("state"))).count());result.put("pending",tasks.stream().filter(t->"SUBMITTED".equals(t.get("state"))).count());result.put("overdue",tasks.stream().filter(t->Set.of("ASSIGNED","RETURNED").contains(t.get("state"))&&!LocalDateTime.now(clock).isBefore(date(t.get("deadline")))).count());
 result.put("pendingIdentity",jdbc.queryForObject("SELECT COUNT(*) FROM tb_input_record r WHERE "+where+" AND r.identity_review_state='PENDING'",Long.class,q,q));result.put("pendingDuplicate",jdbc.queryForObject("SELECT COUNT(*) FROM tb_input_record r LEFT JOIN tb_event_source_link l ON l.record_id=r.id WHERE "+where+" AND r.identity_review_state='CONFIRMED' AND l.record_id IS NULL",Long.class,q,q));result.put("pendingChanges",jdbc.queryForObject("SELECT COUNT(*) FROM tb_record_change c JOIN tb_input_record r ON r.id=c.record_id WHERE c.state='PENDING' AND "+where,Long.class,q,q));
 Map<String,Long> words=new TreeMap<>();if(p.canReadAll())jdbc.queryForList("SELECT h.term,COUNT(DISTINCT pr.person_id,h.event_id) AS total FROM tb_person_risk pr JOIN JSON_TABLE(pr.snapshot,'$.keywordHits[*]' COLUMNS(event_id BIGINT PATH '$.eventId',NESTED PATH '$.terms[*]' COLUMNS(term VARCHAR(100) PATH '$'))) h WHERE (?='' OR EXISTS(SELECT 1 FROM tb_input_record r JOIN tb_event_source_link l ON l.record_id=r.id WHERE l.effective_event_id=h.event_id AND "+where+")) GROUP BY h.term",q,q,q).forEach(r->words.put(r.get("term").toString(),((Number)r.get("total")).longValue()));result.put("keywords",words);
 result.put("risks",p.canReadAll()?jdbc.queryForList("SELECT JSON_UNQUOTE(JSON_EXTRACT(pr.snapshot,'$.finalLevel')) AS level,COUNT(*) AS total FROM tb_person_risk pr JOIN tb_person p ON p.id=pr.person_id WHERE p.merged_into IS NULL AND (LOCATE(?,p.name)>0 OR EXISTS(SELECT 1 FROM tb_input_record x WHERE x.matched_person_id=p.id AND x.is_deleted=0 AND LOCATE(?,x.problem_description)>0)) GROUP BY level",q,q):List.of());return result;
 }
 @GetMapping("/keyword") public Object keyword(Authentication a,@RequestParam String term,@RequestParam(defaultValue="")String q){if(!actor(a).canReadAll())throw new ResponseStatusException(HttpStatus.FORBIDDEN);InputChecks.text(term,100,"关键词");return jdbc.queryForList("SELECT pr.person_id AS personId,h.event_id AS eventId,JSON_ARRAYAGG(h.evidence) AS evidence FROM tb_person_risk pr JOIN JSON_TABLE(pr.snapshot,'$.keywordHits[*]' COLUMNS(event_id BIGINT PATH '$.eventId',evidence JSON PATH '$.evidence',NESTED PATH '$.terms[*]' COLUMNS(term VARCHAR(100) PATH '$'))) h WHERE h.term=? AND (?='' OR EXISTS(SELECT 1 FROM tb_input_record r JOIN tb_event_source_link l ON l.record_id=r.id WHERE l.effective_event_id=h.event_id AND r.is_deleted=0 AND (LOCATE(?,r.party_name)>0 OR LOCATE(?,r.problem_description)>0))) GROUP BY pr.person_id,h.event_id",term,q,q,q);}
 @GetMapping("/export") public ResponseEntity<byte[]> export(Authentication a,@RequestParam String kind,@RequestParam(defaultValue="")String q){Object data=switch(kind){case "events"->records(actor(a),q);case "risks"->risks(a,q);case "statistics"->dashboard(a,q);default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"导出类型无效");};StringBuilder csv=new StringBuilder("\ufeff筛选条件,"+cell(q)+"\r\n");if(data instanceof List<?> list){if(!list.isEmpty()){var columns=((Map<?,?>)list.getFirst()).keySet();csv.append(columns.stream().map(Object::toString).collect(java.util.stream.Collectors.joining(","))).append("\r\n");for(Object item:list){Map<?,?> row=(Map<?,?>)item;csv.append(columns.stream().map(k->cell(row.get(k))).collect(java.util.stream.Collectors.joining(","))).append("\r\n");}}else csv.append("无结果\r\n");}else{csv.append("指标,数值\r\n");((Map<?,?>)data).forEach((k,v)->csv.append(cell(k)).append(',').append(cell(v)).append("\r\n"));}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=insights.csv").contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).body(csv.toString().getBytes(StandardCharsets.UTF_8));}
 private String cell(Object value){String s=Objects.toString(value,"");String lead=s.stripLeading();if((!lead.isEmpty()&&"=+@-".indexOf(lead.charAt(0))>=0)||s.startsWith("\t")||s.startsWith("\r"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 private boolean same(Long id,Object value){return value instanceof Number n && id.longValue()==n.longValue();}
 private LocalDateTime date(Object o){return o instanceof java.sql.Timestamp t?t.toLocalDateTime():(LocalDateTime)o;}
 @GetMapping("/history") public Object history(Authentication a,@RequestParam(defaultValue="")String type,@RequestParam(required=false)Long objectId,@RequestParam(required=false)Long personId,@RequestParam(defaultValue="")String from,@RequestParam(defaultValue="")String to){
 var p=actor(a);LocalDateTime start=null,end=null;try{if(!from.isEmpty())start=LocalDateTime.parse(from);if(!to.isEmpty())end=LocalDateTime.parse(to);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"时间格式无效");}InputChecks.require(start==null||end==null||!start.isAfter(end),"时间范围无效");
 List<Map<String,Object>> rows=new ArrayList<>();
 if(p.canReadAll()){
 rows.addAll(jdbc.queryForList("SELECT o.*,CAST(JSON_UNQUOTE(JSON_EXTRACT(t.dispatch_snapshot,'$.personId')) AS UNSIGNED) AS from_person_id,COALESCE(t.person_id,al.person_id,r.matched_person_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(o.after_data,'$.personId')) AS UNSIGNED)) AS person_id,o.gmt_create AS created_at FROM tb_operation_log o LEFT JOIN tb_handling_task t ON o.target_type LIKE 'TASK%' AND t.id=o.target_id LEFT JOIN tb_alert al ON o.target_type='ALERT_REVIEW' AND al.id=o.target_id LEFT JOIN tb_input_record r ON o.target_type IN ('EVENT_SUBMISSION','EVENT_TAGS','IDENTITY_REVIEW','DUPLICATE_REVIEW') AND r.id=o.target_id WHERE o.target_type IS NOT NULL"));
 rows.addAll(jdbc.queryForList("SELECT c.*,'ARCHIVE' AS target_type,c.from_person_id AS target_id FROM tb_archive_change c"));
 rows.addAll(jdbc.queryForList("SELECT c.*,'RECORD_CHANGE' AS target_type,c.record_id AS target_id,r.matched_person_id AS person_id FROM tb_record_change c JOIN tb_input_record r ON r.id=c.record_id"));
 rows.addAll(jdbc.queryForList("SELECT c.*,'ADJUSTMENT' AS target_type,c.person_id AS target_id FROM tb_risk_adjustment c"));
 rows.addAll(jdbc.queryForList("SELECT c.*,'EXCLUSION' AS target_type,c.event_id AS target_id,e.person_id FROM tb_keyword_exclusion c JOIN tb_effective_event e ON e.id=c.event_id"));
 rows.addAll(jdbc.queryForList("SELECT c.*,'RULE' AS target_type,c.id AS target_id FROM tb_rule_release c"));
 rows.addAll(jdbc.queryForList("SELECT c.*,'ALERT' AS target_type,c.alert_id AS target_id,a.person_id FROM tb_alert_review c JOIN tb_alert a ON a.id=c.alert_id"));
 }else if(p.canReadDepartment()) rows.addAll(jdbc.queryForList("SELECT c.*,'RECORD_CHANGE' AS target_type,c.record_id AS target_id,r.matched_person_id AS person_id FROM tb_record_change c JOIN tb_input_record r ON r.id=c.record_id WHERE c.department_id=?",p.departmentId()));
 if(p.canReadAll()||p.roles().contains("DEPARTMENT_HANDLER")) rows.addAll(jdbc.queryForList("SELECT n.*,'TASK' AS target_type,n.task_id AS target_id,t.person_id FROM tb_task_note n JOIN tb_handling_task t ON t.id=n.task_id WHERE (?=1 OR t.department_id=?)",p.canReadAll(),p.departmentId()));
 final LocalDateTime low=start,high=end;
 return rows.stream().filter(r->type.isEmpty()||type.equals(r.get("target_type"))).filter(r->objectId==null||objectId.equals(((Number)r.get("target_id")).longValue())).filter(r->personId==null||same(personId,r.get("person_id"))||same(personId,r.get("from_person_id"))||same(personId,r.get("to_person_id"))).filter(r->low==null||!date(r.get("created_at")).isBefore(low)).filter(r->high==null||!date(r.get("created_at")).isAfter(high)).sorted((x,y)->date(y.get("created_at")).compareTo(date(x.get("created_at")))).toList();
 }
}
